import json,uuid
from playwright.sync_api import expect

def verify_instant_table(page,project,mount,send,envelope,settle,restart):
 prefix='Example.ButtonGame::';score=prefix+'Score';twin=prefix+'TableTwin';amount='data:["amount"]';tags='data:["tags"]';meta_description='value:"description"'
