 builder.locator('[data-table-probe]').select_option(prefix+'ZBroken');expect(builder.locator('[data-table-fields-error]')).to_be_visible(timeout=60000);ready();expect(builder.locator('[data-table-object]')).to_have_count(3);invoke('editDraft',{'id':prefix+'ZBroken','text':originals['ZBroken.celem'].decode(),'revision':state()['draft']['revision']});builder.locator('[data-table-probe]').select_option(score);expect(builder.locator('[data-table-fields-error]')).to_have_count(0,timeout=60000);ready();assert any(field['id']==meta_description for field in state()['tableOptions']['fields'])
 for checkbox in builder.locator('[data-table-object]').all():checkbox.set_checked(checkbox.get_attribute('data-table-object') in [score,twin])
