 builder.locator('[data-table-request]').fill('두 객체의 실제 능력치 비교');builder.locator('[data-table-create]').click();w=page.locator('.window[data-key^="table:"]');expect(w.locator('[data-table-cell="'+score+'"][data-column=\''+amount+'\']')).to_have_value('9223372036854775807',timeout=60000);ready()
