 w.locator('[data-table-configure]').click();ready();builder.locator('[data-table-object="'+twin+'"]').check();builder.locator('[data-table-field=\''+tags+'\']').check();builder.locator('[data-table-create]').click();expect(w.locator('[data-table-row]')).to_have_count(2,timeout=60000);ready()
