 heading.locator('[data-direction="-1"]').click();assert w.locator('thead [data-table-column]').evaluate_all('es=>es.map(e=>e.dataset.tableColumn)')==['description',amount,meta_description,'initial',tags]
 w.locator('[data-table-value-sort=\''+amount+'\']').click();assert w.locator('[data-table-row]').evaluate_all('es=>es.map(e=>e.dataset.tableRow)')==[twin,score];w.locator('[data-table-value-sort=\''+amount+'\']').click();assert w.locator('[data-table-row]').evaluate_all('es=>es.map(e=>e.dataset.tableRow)')==[score,twin];w.locator('[data-table-sort]').click()
