 expect(cell(score,amount)).to_have_value('5');action(score,amount).click();ready();expect(cell(score,amount)).to_have_value('5');assert row(score)['cellInfo'][amount]['valueJson']=='9223372036854775806';action(score,amount,'Cancel').click();expect(cell(score,amount)).to_have_value('9223372036854775806')
