 # This source hash is current but a stale row version never mutates the peer.
 current=state()['tables'][0];old={r['id']:{k:r[k] for k in ['revision','textHash','viewHash']} for r in before}
 invoke('editTable',{'table':current['table'],'ids':[score,twin],'field':amount,'valueJson':'7','versions':old,'operation':'set'},False);assert row(twin)['cellInfo'][amount]['valueJson']=='9223372036854775806'
 w.locator('[data-table-save]').click();ready();cell(score,tags).fill('[8,9]')
 page.set_viewport_size({'width':1440,'height':1000})
